import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int limit = input.nextInt();
        int total = 0;
        int odd = 1;
        while (odd <= limit) {
            total = total + odd;
            odd = odd + 2;
        }
        System.out.println(total);
    }
}

