import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int limit = input.nextInt();
        int product = 1;
        for (int i = 1; i <= limit; i++) {
            product = product * i;
        }
        System.out.println(product);
    }
}

